
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_c_optc_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_c_optc", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-6.582704249298268e-02, -6.496814831942421e-02, -6.373489175467155e-02, -6.196515742460942e-02, -5.942751765891944e-02, -5.579291223052045e-02, -5.059985324502748e-02, -4.323789277970798e-02, -3.312602444325799e-02, -2.110642483289327e-02, -1.465774288290185e-02, -3.535068204978212e-02, -4.103748581018532e-02, -3.021773547466933e-02, -1.628582061654558e-02, -4.046660653184195e-03, -2.077722984875089e-04, -1.562182502681649e-06, -1.328296673113155e-09, -4.923946940810379e-14]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


